function stworzWitacza(powitanie) {
  return function (imie) {
    return `${powitanie}, ${imie}!`;
  };
}

const witajPolski = stworzWitacza("Czesc");
const witajAngielski = stworzWitacza("Hello");

console.log(witajPolski("Kasia"));    // "Czesc, Kasia!"
console.log(witajAngielski("John"));  // "Hello, John!"

