function wersjaZLet(cena, rabatProcent) {
  let stawka = rabatProcent / 100;
  let kwotaRabatu = cena * stawka;
  let wynik = cena - kwotaRabatu;
  return wynik;
}

// PO (poprawnie):
function obliczCeneKoncowa(cena, rabatProcent) {
  const stawka = rabatProcent / 100;
  const kwotaRabatu = cena * stawka;
  const wynik = cena - kwotaRabatu;
  return wynik;
}

console.log(obliczCeneKoncowa(200, 10)); // 180

function przetworzZamowienie(cenaJednostkowa, ilosc) {
  const wartoscZamowienia = cenaJednostkowa * ilosc;
  let statusRealizacji = "oczekujace";

  if (wartoscZamowienia > 0) {
    statusRealizacji = "potwierdzone";
  }

  return { wartoscZamowienia, statusRealizacji };
}

console.log(przetworzZamowienie(50, 3));
// { wartoscZamowienia: 150, statusRealizacji: 'potwierdzone' }

