function podsumujKoszyk(produkty) {
  let suma = 0;
  for (let i = 0; i < produkty.length; i++) {
    suma = suma + produkty[i];
  }
  const wynikKoncowy = suma.toFixed(2);
  return wynikKoncowy;
}

console.log(podsumujKoszyk([19.99, 5.5, 12.25])); // "37.74"
